     1→/**
     2→ * auth 路由契约测试（质量优化 Stage 2）：登录 / 当前用户 / 改密 / OIDC 入口。
     3→ * 覆盖：成功路径 + 鉴权失败（401/403）+ 参数校验（400）+ 业务错误码。
     4→ */
     5→import { describe, it, expect, beforeEach, vi } from 'vitest';
     6→import request from 'supertest';
     7→import express from 'express';
     8→import { applyTestEnv, activeUserRow, tokenFor, dbStub, buildApp } from './routeTestKit';
     9→
    10→const querySpy = vi.fn();
    11→vi.mock('../infra/db', () => ({ getPool: () => ({ query: (...args: unknown[]) => querySpy(...args) }) }));
    12→
    13→import authRoutes from './auth';
    14→import { authMiddleware } from '../auth/auth';
    15→import { hashPassword } from '../auth/passwords';
    16→
    17→applyTestEnv();
    18→
    19→const app = buildApp('/api/auth', authRoutes);
    20→
    21→/** 登录成功行（真实哈希，走真实 verifyPassword 链路） */
    22→const loginRow = (over: Record<string, unknown> = {}) => ({
    23→  id: 7,
    24→  username: 'zhangsan',
    25→  password_hash: hashPassword('Str0ng#Pass1'),
    26→  display_name: '张三',
    27→  department: '风险部',
    28→  role: 'ANALYST',
    29→  status: 'ACTIVE',
    30→  must_change_password: 0,
    31→  ...over,
    32→});
    33→
    34→beforeEach(() => {
    35→  querySpy.mockReset();
    36→});
    37→
    38→describe('POST /api/auth/login：登录契约', () => {
    39→  it('参数缺失或类型不符 → 400', async () => {
    40→    const res = await request(app).post('/api/auth/login').send({ username: 'zhangsan' });
    41→    expect(res.status).toBe(400);
    42→    expect(res.body.error).toBe('请输入用户名和密码');
    43→    const res2 = await request(app).post('/api/auth/login').send({ username: '  ', password: 'x' });
    44→    expect(res2.status).toBe(400);
    45→  });
    46→
    47→  it('用户不存在 → 401 且文案统一（不泄露账号是否存在）', async () => {
    48→    querySpy.mockImplementation(dbStub([{ match: 'FROM users WHERE username', rows: [] }]));
    49→    const res = await request(app).post('/api/auth/login').send({ username: 'nobody', password: 'Str0ng#Pass1' });
    50→    expect(res.status).toBe(401);
    51→    expect(res.body.error).toBe('用户名或密码错误');
    52→  });
    53→
    54→  it('密码错误 → 401', async () => {
    55→    querySpy.mockImplementation(dbStub([{ match: 'FROM users WHERE username', rows: [loginRow()] }]));
    56→    const res = await request(app).post('/api/auth/login').send({ username: 'zhangsan', password: 'Wrong#Pass9' });
    57→    expect(res.status).toBe(401);
    58→    expect(res.body.error).toBe('用户名或密码错误');
    59→  });
    60→
    61→  it('账号被禁用 → 403', async () => {
    62→    querySpy.mockImplementation(dbStub([{ match: 'FROM users WHERE username', rows: [loginRow({ status: 'DISABLED' })] }]));
    63→    const res = await request(app).post('/api/auth/login').send({ username: 'zhangsan', password: 'Str0ng#Pass1' });
    64→    expect(res.status).toBe(403);
    65→    expect(res.body.error).toBe('账号已被禁用，请联系管理员');
    66→  });
    67→
    68→  it('登录成功 → 200 返回 token 与用户信息，且 last_login_at 落库、token 可被 /me 接受', async () => {
    69→    querySpy.mockImplementation(
    70→      dbStub([
    71→        { match: 'FROM users WHERE username', rows: [loginRow()] },
    72→        { match: 'UPDATE users SET last_login_at', rows: [] },
    73→        { match: 'must_change_password FROM users WHERE id', rows: [{ ...activeUserRow('ANALYST', 7), username: 'zhangsan', display_name: '张三' }] },
    74→      ]),
    75→    );
    76→    const res = await request(app).post('/api/auth/login').send({ username: 'zhangsan', password: 'Str0ng#Pass1' });
    77→    expect(res.status).toBe(200);
    78→    expect(res.body.success).toBe(true);
    79→    expect(typeof res.body.token).toBe('string');
    80→    expect(res.body.user).toMatchObject({ id: 7, username: 'zhangsan', role: 'ANALYST', displayName: '张三' });
    81→    expect(res.body.user).not.toHaveProperty('password_hash');
    82→    // 真实链路闭环：签发的 token 能通过 authMiddleware 回查
    83→    const me = await request(app).get('/api/auth/me').set('Authorization', `Bearer ${res.body.token}`);
    84→    expect(me.status).toBe(200);
    85→    expect(me.body.user).toMatchObject({ id: 7, username: 'zhangsan' });
    86→  });
    87→
    88→  it('DB 异常 → 500 兜底错误码文案', async () => {
    89→    querySpy.mockImplementation(async () => {
    90→      throw new Error('db down');
    91→    });
    92→    const res = await request(app).post('/api/auth/login').send({ username: 'zhangsan', password: 'Str0ng#Pass1' });
    93→    expect(res.status).toBe(500);
    94→    expect(res.body.error).toBe('登录服务异常');
    95→  });
    96→});
    97→
    98→describe('GET /api/auth/me：鉴权契约', () => {
    99→  it('缺少 token → 401', async () => {
   100→    const res = await request(app).get('/api/auth/me');
   101→    expect(res.status).toBe(401);
   102→    expect(res.body.error).toBe('未登录或登录已过期');
   103→  });
   104→
   105→  it('token 非法/被篡改 → 401', async () => {
   106→    const res = await request(app).get('/api/auth/me').set('Authorization', 'Bearer not-a-jwt');
   107→    expect(res.status).toBe(401);
   108→    expect(res.body.error).toBe('登录状态无效，请重新登录');
   109→  });
   110→
   111→  it('token 有效但用户不存在 → 401', async () => {
   112→    querySpy.mockImplementation(dbStub([{ match: 'FROM users WHERE id', rows: [] }]));
   113→    const res = await request(app).get('/api/auth/me').set('Authorization', `Bearer ${tokenFor('VIEWER', 99)}`);
   114→    expect(res.status).toBe(401);
   115→    expect(res.body.error).toBe('账号不存在或已被禁用');
   116→  });
   117→
   118→  it('token 有效但账号被禁用 → 401', async () => {
   119→    querySpy.mockImplementation(
   120→      dbStub([{ match: 'FROM users WHERE id', rows: [{ ...activeUserRow('VIEWER', 9), status: 'DISABLED' }] }]),
   121→    );
   122→    const res = await request(app).get('/api/auth/me').set('Authorization', `Bearer ${tokenFor('VIEWER', 9)}`);
   123→    expect(res.status).toBe(401);
   124→  });
   125→
   126→  it('token 有效 → 200 返回当前用户（部门缺省归一为空串）', async () => {
   127→    querySpy.mockImplementation(
   128→      dbStub([{ match: 'FROM users WHERE id', rows: [{ ...activeUserRow('ADMIN', 1), department: null }] }]),
   129→    );
   130→    const res = await request(app).get('/api/auth/me').set('Authorization', `Bearer ${tokenFor('ADMIN', 1)}`);
   131→    expect(res.status).toBe(200);
   132→    expect(res.body.user).toMatchObject({ id: 1, role: 'ADMIN', department: '' });
   133→  });
   134→
   135→  it('P0-1 强制改密：must_change_password 用户访问业务接口 → 403 PASSWORD_CHANGE_REQUIRED', async () => {
   136→    querySpy.mockImplementation(
   137→      dbStub([{ match: 'FROM users WHERE id', rows: [{ ...activeUserRow('ANALYST', 5), must_change_password: 1 }] }]),
   138→    );
   139→    const guarded = express();
   140→    guarded.use(express.json());
   141→    guarded.get('/api/business/ping', authMiddleware, (_req, res) => res.json({ ok: true }));
   142→    const res = await request(guarded).get('/api/business/ping').set('Authorization', `Bearer ${tokenFor('ANALYST', 5)}`);
   143→    expect(res.status).toBe(403);
   144→    expect(res.body.code).toBe('PASSWORD_CHANGE_REQUIRED');
   145→  });
   146→});
   147→
   148→describe('POST /api/auth/change-password：改密契约', () => {
   149→  const url = '/api/auth/change-password';
   150→
   151→  it('未登录 → 401', async () => {
   152→    const res = await request(app).post(url).send({ oldPassword: 'a', newPassword: 'b' });
   153→    expect(res.status).toBe(401);
   154→  });
   155→
   156→  it('参数类型不符 → 400', async () => {
   157→    querySpy.mockImplementation(dbStub([{ match: 'FROM users WHERE id', rows: [activeUserRow('ANALYST', 7)] }]));
   158→    const res = await request(app)
   159→      .post(url)
   160→      .set('Authorization', `Bearer ${tokenFor('ANALYST', 7)}`)
   161→      .send({ oldPassword: 'Str0ng#Pass1' });
   162→    expect(res.status).toBe(400);
   163→    expect(res.body.error).toBe('参数格式不正确');
   164→  });
   165→
   166→  it('新密码强度不达标 → 400（长度/复杂度/含用户名）', async () => {
   167→    querySpy.mockImplementation(dbStub([{ match: 'FROM users WHERE id', rows: [activeUserRow('ANALYST', 7)] }]));
   168→    const auth = `Bearer ${tokenFor('ANALYST', 7)}`;
   169→    for (const weak of ['short1', 'alllowercase', 'u7abc123']) {
   170→      const res = await request(app).post(url).set('Authorization', auth).send({ oldPassword: 'Str0ng#Pass1', newPassword: weak });
   171→      expect(res.status, `弱口令 ${weak} 应被拒绝`).toBe(400);
   172→    }
   173→  });
   174→
   175→  it('原密码不正确 → 400', async () => {
