     1→/**
     2→ * SQL 样例库（训练语料）管理路由（Vanna training data CRUD 借鉴）。
     3→ * 读取对所有登录用户开放；登记 / 编辑 / 剔除 / 批量导入仅 ADMIN，
     4→ * 保证 few-shot 语料质量可由管理员持续治理（劣质样例可剔除）。
     5→ */
     6→import { Router } from 'express';
     7→import type { RowDataPacket } from 'mysql2';
     8→import { authMiddleware, requireRole } from '../auth/auth';
     9→import {
    10→  listSqlExamples,
    11→  createSqlExample,
    12→  updateSqlExample,
    13→  deleteSqlExample,
