    22→const router = Router();
    23→router.use(authMiddleware);
    24→
    25→// GET /api/sql-examples?dataSourceId=xxx —— 列出某数据源的全部样例
    26→router.get('/', async (req, res) => {
    27→  const dataSourceId = String(req.query.dataSourceId || '');
    28→  if (!dataSourceId) return res.status(400).json({ error: '缺少 dataSourceId' });
    29→  try {
    30→    const examples = await listSqlExamples(dataSourceId);
    31→    res.json({ examples });
    32→  } catch (err: any) {
    33→    res.status(500).json({ error: `查询样例库失败：${err?.message || '未知错误'}` });
    34→  }
    35→});
    36→
    37→// POST /api/sql-examples（ADMIN）—— 手工登记样例 {dataSourceId,question,sql}
    38→router.post('/', requireRole('ADMIN'), async (req, res) => {
    39→  const { dataSourceId, question, sql } = req.body || {};
    40→  if (typeof dataSourceId !== 'string' || !dataSourceId) return res.status(400).json({ error: '缺少 dataSourceId' });
    41→  const invalid = validateExampleInput({ question, sql });
    42→  if (invalid) return res.status(400).json({ error: invalid });
    43→  const username = String(req.user?.username || 'admin');
    44→  try {
    45→    const example = await createSqlExample({ dataSourceId, question, sql }, username);
    46→    res.json({ ok: true, example });
    47→  } catch (err: any) {
    48→    res.status(500).json({ error: `登记失败：${err?.message || '未知错误'}` });
    49→  }
    50→});
    51→
    52→// POST /api/sql-examples/generate-questions（ADMIN）—— 给一批 SQL 反推问题（冷启动，不入库）
    53→router.post('/generate-questions', requireRole('ADMIN'), async (req, res) => {
    54→  const { sqls } = req.body || {};
    55→  if (!Array.isArray(sqls) || sqls.length === 0) return res.status(400).json({ error: '缺少 sqls 数组' });
    56→  const list = sqls.filter((s: any) => typeof s === 'string' && s.trim()).map((s: string) => s.trim());
    57→  if (list.length === 0) return res.status(400).json({ error: '没有有效的 SQL' });
    58→  if (list.length > 10) return res.status(400).json({ error: '单次最多导入 10 条 SQL' });
    59→  try {
    60→    const pairs = await generateQuestionsForSqls(list);
    61→    res.json({ pairs });
    62→  } catch (err: any) {
    63→    res.status(500).json({ error: `问题反推失败：${err?.message || '未知错误'}` });
    64→  }
    65→});
    66→
    67→// POST /api/sql-examples/bulk（ADMIN）—— 批量保存样例 {dataSourceId, examples:[{question,sql}]}
    68→router.post('/bulk', requireRole('ADMIN'), async (req, res) => {
    69→  const { dataSourceId, examples } = req.body || {};
    70→  if (typeof dataSourceId !== 'string' || !dataSourceId) return res.status(400).json({ error: '缺少 dataSourceId' });
    71→  if (!Array.isArray(examples) || examples.length === 0) return res.status(400).json({ error: '缺少 examples 数组' });
    72→  if (examples.length > 10) return res.status(400).json({ error: '单次最多保存 10 条样例' });
    73→  const username = String(req.user?.username || 'admin');
    74→  let saved = 0;
    75→  try {
    76→    for (const ex of examples) {
    77→      if (validateExampleInput(ex)) continue;
    78→      await createSqlExample({ dataSourceId, question: String(ex.question), sql: String(ex.sql) }, username, 'IMPORT');
    79→      saved++;
    80→    }
    81→    if (saved === 0) return res.status(400).json({ error: '没有可保存的合法样例' });
    82→    res.json({ ok: true, saved });
    83→  } catch (err: any) {
    84→    res.status(500).json({ error: `批量保存失败：${err?.message || '未知错误'}` });
    85→  }
    86→});
    87→
    88→// GET /api/sql-examples/export?dataSourceId=xxx（ADMIN）—— 导出指定数据源的全部样例为 JSON 备份文件
    89→router.get('/export', requireRole('ADMIN'), async (req, res) => {
    90→  const dataSourceId = String(req.query.dataSourceId || '');
    91→  if (!dataSourceId) return res.status(400).json({ error: '缺少 dataSourceId' });
    92→  try {
    93→    const [dsRows] = await getPool().query<RowDataPacket[]>('SELECT name FROM data_sources WHERE id = ?', [dataSourceId]);
    94→    if (dsRows.length === 0) return res.status(404).json({ error: `数据源不存在：${dataSourceId}` });
    95→    const dsName = String(dsRows[0].name || dataSourceId);
    96→    const examples = await listSqlExamples(dataSourceId);
    97→    const exportData = buildSqlExamplesExport(dataSourceId, dsName, examples, String(req.user?.username || 'unknown'));
    98→    const dateStr = new Date().toISOString().split('T')[0];
    99→    const fileName = `SQL样例库-${dsName}-${dateStr}.json`;
   100→    res.setHeader('Content-Type', 'application/json; charset=utf-8');
   101→    res.setHeader(
   102→      'Content-Disposition',
   103→      `attachment; filename="sql-examples-${dataSourceId}-${dateStr}.json"; filename*=UTF-8''${encodeURIComponent(fileName)}`
   104→    );
   105→    res.send(JSON.stringify(exportData, null, 2));
   106→  } catch (err: any) {
   107→    logger.error('[SQL Examples Export Error]', err);
   108→    res.status(500).json({ error: `导出失败：${err?.message || '未知错误'}` });
   109→  }
   110→});
   111→
   112→/**
   113→ * POST /api/sql-examples/import（ADMIN）—— 从 JSON 备份文件恢复样例到指定数据源。
   114→ * body: {
   115→ *   fileData: object,                                  // 导出文件的完整 JSON 内容（必填，type='sql-examples'）
   116→ *   dataSourceId?: string,                             // 目标数据源（缺省用文件中的来源数据源）
   117→ *   mergeStrategy?: 'skip' | 'overwrite' | 'append',   // 同问题冲突处理：跳过/覆盖/重复新增（默认 skip）
   118→ *   dryRun?: boolean                                   // 仅预检不写库（默认 false）
   119→ * }
   120→ */
   121→router.post('/import', requireRole('ADMIN'), async (req, res) => {
   122→  try {
   123→    const { fileData, mergeStrategy = 'skip', dryRun = false } = req.body || {};
   124→    if (!fileData || typeof fileData !== 'object') {
   125→      return res.status(400).json({ error: '缺少 fileData（备份文件的 JSON 内容）' });
   126→    }
   127→    if (!['skip', 'overwrite', 'append'].includes(mergeStrategy)) {
   128→      return res.status(400).json({ error: 'mergeStrategy 必须是 skip / overwrite / append' });
   129→    }
   130→    if (fileData.type !== 'sql-examples' || !Array.isArray(fileData.examples)) {
   131→      return res.status(400).json({ error: '无法识别的文件格式：应为 SQL 样例库导出文件（type=sql-examples）' });
   132→    }
   133→    if (fileData.examples.length === 0) {
   134→      return res.status(400).json({ error: '文件中没有可导入的样例' });
   135→    }
   136→    const dataSourceId = String(req.body.dataSourceId || fileData.dataSourceId || '');
   137→    if (!dataSourceId) return res.status(400).json({ error: '缺少目标数据源 dataSourceId（文件中也没有来源信息）' });
   138→
   139→    const [dsRows] = await getPool().query<RowDataPacket[]>('SELECT id, name FROM data_sources WHERE id = ?', [dataSourceId]);
   140→    if (dsRows.length === 0) return res.status(404).json({ error: `目标数据源不存在：${dataSourceId}` });
   141→
   142→    const username = String(req.user?.username || 'admin');
   143→    const result = await importSqlExamples(dataSourceId, fileData.examples, mergeStrategy, !!dryRun, username);
   144→    logger.info('[SQL Examples Import]', {
   145→      dryRun: result.dryRun,
   146→      strategy: mergeStrategy,
   147→      dataSourceId,
   148→      imported: result.importedCount,
   149→      updated: result.updatedCount,
   150→      skipped: result.skippedCount,
   151→      errors: result.errorCount,
   152→    });
   153→    res.json({ ...result, dataSourceId, dataSourceName: String(dsRows[0].name || dataSourceId) });
   154→  } catch (err: any) {
   155→    logger.error('[SQL Examples Import Error]', err);
   156→    res.status(500).json({ error: `导入失败：${err?.message || '未知错误'}` });
   157→  }
   158→});
   159→
   160→// PUT /api/sql-examples/:id（ADMIN）—— 编辑样例 {question,sql}
   161→router.put('/:id', requireRole('ADMIN'), async (req, res) => {
   162→  const id = Number(req.params.id);
   163→  if (!Number.isFinite(id)) return res.status(400).json({ error: '无效的样例 ID' });
   164→  const invalid = validateExampleInput(req.body || {});
   165→  if (invalid) return res.status(400).json({ error: invalid });
   166→  try {
   167→    const { question, sql } = req.body;
   168→    const updated = await updateSqlExample(id, { question, sql });
   169→    if (!updated) return res.status(404).json({ error: '样例不存在' });
   170→    res.json({ ok: true });
   171→  } catch (err: any) {
   172→    res.status(500).json({ error: `保存失败：${err?.message || '未知错误'}` });
   173→  }
   174→});
   175→
   176→// DELETE /api/sql-examples/:id（ADMIN）—— 剔除劣质样例
   177→router.delete('/:id', requireRole('ADMIN'), async (req, res) => {
   178→  const id = Number(req.params.id);
   179→  if (!Number.isFinite(id)) return res.status(400).json({ error: '无效的样例 ID' });
   180→  try {
   181→    const deleted = await deleteSqlExample(id);
   182→    if (!deleted) return res.status(404).json({ error: '样例不存在' });
   183→    res.json({ ok: true });
   184→  } catch (err: any) {
   185→    res.status(500).json({ error: `删除失败：${err?.message || '未知错误'}` });
   186→  }
   187→});
   188→
   189→export default router;
