   234→// ---------- SQL 样例库管理（管理员维护的训练语料） ----------
   235→
   236→export interface SqlExampleRecord {
   237→  id: number;
   238→  dataSourceId: string;
   239→  question: string;
   240→  sql: string;
   241→  source: 'MANUAL' | 'FEEDBACK_UP' | 'IMPORT';
   242→  createdBy: string;
   243→  createdAt: string;
   244→}
   245→
   246→function toExampleRecord(r: any): SqlExampleRecord {
   247→  return {
   248→    id: Number(r.id),
   249→    dataSourceId: String(r.data_source_id),
   250→    question: String(r.question),
   251→    sql: String(r.sql_text),
   252→    source: (String(r.source) as SqlExampleRecord['source']) || 'MANUAL',
   253→    createdBy: String(r.created_by || ''),
   254→    createdAt: r.created_at ? new Date(r.created_at).toISOString() : '',
   255→  };
   256→}
   257→
   258→/** 样例入参校验；返回错误文案或 null */
   259→export function validateExampleInput(input: { question?: unknown; sql?: unknown }): string | null {
   260→  const q = typeof input.question === 'string' ? input.question.trim() : '';
   261→  if (!q) return '问题不能为空';
   262→  if (q.length > 500) return '问题不能超过 500 字';
   263→  const sql = typeof input.sql === 'string' ? input.sql.trim() : '';
   264→  if (!sql) return 'SQL 不能为空';
   265→  if (sql.length > 2000) return 'SQL 不能超过 2000 字';
   266→  if (!/^select\b/i.test(sql)) return '仅支持登记 SELECT 查询样例';
   267→  return null;
   268→}
   269→
   270→export async function listSqlExamples(dataSourceId: string): Promise<SqlExampleRecord[]> {
   271→  const [rows] = await getPool().query<RowDataPacket[]>(
   272→    'SELECT * FROM sql_examples WHERE data_source_id = ? ORDER BY id DESC',
   273→    [dataSourceId]
   274→  );
   275→  return rows.map(toExampleRecord);
   276→}
   277→
   278→export async function createSqlExample(
   279→  input: { dataSourceId: string; question: string; sql: string },
   280→  createdBy: string,
   281→  source: 'MANUAL' | 'IMPORT' = 'MANUAL'
   282→): Promise<SqlExampleRecord> {
   283→  const embeddingJson = await embedExampleQuestion(input.question);
   284→  const result: any = await getPool().query(
   285→    'INSERT INTO sql_examples (data_source_id, question, sql_text, source, created_by, embedding) VALUES (?, ?, ?, ?, ?, ?)',
   286→    [input.dataSourceId.slice(0, 64), input.question.trim().slice(0, 500), normalizeSql(input.sql).slice(0, 2000), source, createdBy.slice(0, 50), embeddingJson]
   287→  );
   288→  const insertId = Number(result[0]?.insertId);
   289→  const [rows] = await getPool().query<RowDataPacket[]>('SELECT * FROM sql_examples WHERE id = ?', [insertId]);
   290→  return toExampleRecord(rows[0]);
   291→}
   292→
   293→export async function updateSqlExample(
   294→  id: number,
   295→  input: { question: string; sql: string }
   296→): Promise<boolean> {
   297→  // P1-3：问题变更时向量同步重算，避免旧向量与新问题语义脱节
   298→  const embeddingJson = await embedExampleQuestion(input.question);
   299→  const result: any = await getPool().query(
   300→    'UPDATE sql_examples SET question = ?, sql_text = ?, embedding = ? WHERE id = ?',
   301→    [input.question.trim().slice(0, 500), normalizeSql(input.sql).slice(0, 2000), embeddingJson, id]
   302→  );
   303→  return Number(result[0]?.affectedRows) > 0;
   304→}
   305→
   306→export async function deleteSqlExample(id: number): Promise<boolean> {
   307→  const result: any = await getPool().query('DELETE FROM sql_examples WHERE id = ?', [id]);
   308→  return Number(result[0]?.affectedRows) > 0;
   309→}
   310→
   311→/** P2-8 冷启动：给一批 SQL 反推自然语言问题（Vanna generate_question 思路），不入库，供前端预览确认 */
   312→export async function generateQuestionsForSqls(sqls: string[]): Promise<{ sql: string; question: string }[]> {
   313→  const out: { sql: string; question: string }[] = [];
   314→  for (const raw of sqls.slice(0, 10)) {
   315→    const sql = normalizeSql(raw).slice(0, 2000);
   316→    if (!sql || !/^select\b/i.test(sql)) {
   317→      out.push({ sql, question: '' });
   318→      continue;
   319→    }
   320→    let question: string;
   321→    try {
   322→      const text = await callLLMJson(
   323→        '你是数据分析助手。给定一条 SELECT 查询，用一句简洁的中文自然语言问题描述它的分析意图（不要提及表名细节，聚焦业务含义）。只输出问题本身，不要任何前缀、引号或解释。',
   324→        `SQL：${sql}`
   325→      );
   326→      question = String(text || '').trim().replace(/^["']|["']$/g, '').slice(0, 200);
   327→    } catch {
   328→      question = '';
   329→    }
   330→    out.push({ sql, question });
   331→  }
   332→  return out;
   333→}
   334→
   335→// ---------- SQL 样例库导入导出（管理员备份/迁移，与知识库导入导出同模式） ----------
   336→
   337→/** 样例库导出文件格式（JSON 备份） */
   338→export interface SqlExamplesExportFile {
   339→  version: '1.0';
   340→  type: 'sql-examples';
   341→  exportedAt: string;
   342→  exportedBy: string;
   343→  dataSourceId: string;
   344→  dataSourceName: string;
   345→  exampleCount: number;
   346→  examples: Array<{ question: string; sql: string; source: string; createdBy: string; createdAt: string }>;
   347→}
   348→
   349→/** 组装样例库导出文件（纯函数可单测；剥离库内 id，保留来源标记供追溯） */
   350→export function buildSqlExamplesExport(
   351→  dataSourceId: string,
   352→  dataSourceName: string,
   353→  examples: SqlExampleRecord[],
   354→  exportedBy: string
   355→): SqlExamplesExportFile {
   356→  return {
   357→    version: '1.0',
   358→    type: 'sql-examples',
   359→    exportedAt: new Date().toISOString(),
   360→    exportedBy,
   361→    dataSourceId,
   362→    dataSourceName,
   363→    exampleCount: examples.length,
   364→    examples: examples.map((ex) => ({
   365→      question: ex.question,
   366→      sql: ex.sql,
   367→      source: ex.source,
   368→      createdBy: ex.createdBy,
   369→      createdAt: ex.createdAt,
   370→    })),
   371→  };
   372→}
   373→
   374→/** 样例导入冲突处理策略：同问题样例 跳过 / 覆盖更新 / 重复新增 */
   375→export type SqlExampleMergeStrategy = 'skip' | 'overwrite' | 'append';
   376→
   377→export interface SqlExampleImportResult {
   378→  success: boolean;
   379→  dryRun: boolean;
   380→  mergeStrategy: SqlExampleMergeStrategy;
   381→  importedCount: number;
   382→  updatedCount: number;
   383→  skippedCount: number;
   384→  errorCount: number;
   385→  errors: Array<{ question: string; message: string }>;
   386→  summary: { totalItems: number; newItems: number; conflictItems: number; invalidItems: number };
   387→}
   388→
   389→/** 单次导入文件条目上限（防滥用；few-shot 语料库治理量级远小于此） */
   390→const MAX_IMPORT_EXAMPLES = 500;
   391→
   392→/**
   393→ * 从导出文件恢复 SQL 样例到指定数据源（仅 ADMIN 经路由调用）。
   394→ * - 每条经 validateExampleInput 校验（与手工登记同一口径：仅 SELECT、长度限制）；
   395→ * - 冲突判定：目标数据源下相同问题（trim 后）；skip 跳过 / overwrite 覆盖 SQL（重算向量）/ append 照常新建；
   396→ * - 新增样例 source 统一记 IMPORT（无论文件中 source 是什么，导入行为本身即来源）；
   397→ * - 文件内部同问题：首条处理后记入冲突集合，后续按冲突策略处理（与知识库导入语义一致）；
   398→ * - dryRun 仅统计不写库（也不触发 embedding 调用）。
   399→ */
   400→export async function importSqlExamples(
   401→  dataSourceId: string,
   402→  items: unknown[],
   403→  strategy: SqlExampleMergeStrategy,
   404→  dryRun: boolean,
   405→  actor: string
   406→): Promise<SqlExampleImportResult> {
   407→  const result: SqlExampleImportResult = {
   408→    success: true,
   409→    dryRun,
   410→    mergeStrategy: strategy,
   411→    importedCount: 0,
   412→    updatedCount: 0,
   413→    skippedCount: 0,
   414→    errorCount: 0,
   415→    errors: [],
   416→    summary: { totalItems: items.length, newItems: 0, conflictItems: 0, invalidItems: 0 },
   417→  };
   418→
   419→  // 冲突判定依据：目标数据源现有 问题 → id 映射
   420→  const [rows] = await getPool().query<RowDataPacket[]>(
   421→    'SELECT id, question FROM sql_examples WHERE data_source_id = ?',
   422→    [dataSourceId]
   423→  );
   424→  const existingByQuestion = new Map<string, number>(rows.map((r: any) => [String(r.question), Number(r.id)]));
   425→
   426→  for (const raw of items.slice(0, MAX_IMPORT_EXAMPLES)) {
   427→    const question = typeof (raw as any)?.question === 'string' ? String((raw as any).question).trim() : '';
   428→    const sql = typeof (raw as any)?.sql === 'string' ? String((raw as any).sql).trim() : '';
   429→    const invalid = validateExampleInput({ question, sql });
   430→    if (invalid) {
   431→      result.summary.invalidItems++;
   432→      result.errorCount++;
   433→      result.errors.push({ question: question || '(空问题)', message: invalid });
   434→      continue;
   435→    }
   436→    const conflictId = existingByQuestion.get(question);
   437→    try {
   438→      if (conflictId !== undefined && strategy !== 'append') {
   439→        result.summary.conflictItems++;
   440→        if (strategy === 'skip') {
   441→          result.skippedCount++;
   442→          continue;
   443→        }
   444→        // overwrite：覆盖更新（updateSqlExample 同步重算问题向量）
   445→        if (!dryRun) {
   446→          const ok = await updateSqlExample(conflictId, { question, sql });
   447→          if (!ok) throw new Error('样例不存在或已被删除');
   448→        }
   449→        result.updatedCount++;
   450→        continue;
   451→      }
   452→      if (conflictId !== undefined) result.summary.conflictItems++; // append：同问题照常新建
   453→      else result.summary.newItems++;
   454→      if (!dryRun) {
   455→        const created = await createSqlExample({ dataSourceId, question, sql }, actor, 'IMPORT');
   456→        existingByQuestion.set(question, created.id);
   457→      } else {
   458→        existingByQuestion.set(question, -1);
   459→      }
   460→      result.importedCount++;
   461→    } catch (err: any) {
   462→      result.errorCount++;
   463→      result.errors.push({ question, message: err?.message || '未知错误' });
   464→    }
   465→  }
   466→
   467→  result.success = result.errorCount === 0;
   468→  return result;
   469→}
