   206→/** 检索与问题最相关的知识片段并格式化为 prompt 块（任何异常降级为空串，不阻断问数） */
   207→export async function retrieveKnowledgeSnippets(
   208→  dataSourceId: string,
   209→  question: string,
   210→  topK = TOP_K_CHUNKS
   211→): Promise<string> {
   212→  try {
   213→    const [rows] = await getPool().query<KbChunkSelectRow[]>(
   214→      'SELECT title, chunk_text, embedding_json FROM knowledge_base WHERE data_source_id = ?',
   215→      [dataSourceId]
   216→    );
   217→    const chunks: KnowledgeChunk[] = rows.map((r) => {
   218→      let embedding: number[] | null;
   219→      try {
   220→        embedding = r.embedding_json ? JSON.parse(r.embedding_json) : null;
   221→      } catch {
   222→        embedding = null;
   223→      }
   224→      return { title: String(r.title || ''), text: String(r.chunk_text || ''), embedding: Array.isArray(embedding) ? embedding : null };
   225→    });
   226→    if (chunks.length === 0) return '';
   227→
   228→    let questionEmbedding: number[] | null = null;
   229→    try {
   230→      questionEmbedding = await callEmbedding(question, 'query');
   231→    } catch {
   232→      questionEmbedding = null;
   233→    }
   234→    return formatKnowledgeSnippets(rankChunks(question, chunks, questionEmbedding, topK));
   235→  } catch {
   236→    return '';
   237→  }
   238→}
