    46→  if (!src) return [];
    47→
    48→  // 先按换行切段落，逐段合并到 chunkSize 以内
    49→  const paras = src.split(/\n+/).map((p) => p.trim()).filter(Boolean);
    50→  const merged: string[] = [];
    51→  let buf = '';
    52→  for (const p of paras) {
    53→    if (buf && (buf.length + 1 + p.length) > chunkSize) {
    54→      merged.push(buf.trim());
    55→      buf = buf.slice(-overlap) + '\n' + p;
    56→    } else {
    57→      buf = buf ? `${buf}\n${p}` : p;
    58→    }
    59→  }
    60→  if (buf.trim()) merged.push(buf.trim());
    61→
    62→  // 超长单块强制按步长切
    63→  const out: string[] = [];
    64→  const step = Math.max(1, chunkSize - overlap);
    65→  for (const c of merged) {
    66→    if (c.length <= chunkSize) {
    67→      out.push(c);
    68→      continue;
    69→    }
    70→    for (let i = 0; i < c.length; i += step) {
    71→      out.push(c.slice(i, i + chunkSize));
    72→    }
    73→  }
    74→  return out.filter((c) => c.trim().length > 0);
    75→}
