    77→/** 余弦相似度：向量维度不一致或零向量时返回 0 */
    78→export function cosineSimilarity(a: number[], b: number[]): number {
    79→  if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length || a.length === 0) return 0;
    80→  let dot = 0;
    81→  let na = 0;
    82→  let nb = 0;
    83→  for (let i = 0; i < a.length; i++) {
    84→    dot += a[i] * b[i];
    85→    na += a[i] * a[i];
    86→    nb += b[i] * b[i];
    87→  }
    88→  if (na === 0 || nb === 0) return 0;
    89→  return dot / (Math.sqrt(na) * Math.sqrt(nb));
    90→}
