    98→/**
    99→ * 排序检索：question 与 chunk 均可用向量时走余弦相似度，否则降级 bigram 关键词。
   100→ * 返回得分最高的 topK 个片段；向量模式过滤低于 knowledgeMinScore() 的无关片段，
   101→ * bigram 降级模式维持过滤得分 ≤0（量纲不同，不套用向量阈值）；
   102→ * 同一文档（title）最多入选 maxPerDoc 块，避免单一长字典文档占满注入槽位；
   103→ * reserveGuided 为 true 时，为标题命中 GUIDED_DOC_KEYWORDS 的最高分块保留一个槽位，
   104→ * 保证口径/指南类知识（如「高频指标口径速查」）在字段字典相似度更高时仍能注入。
   105→ */
   106→export function rankChunks(
   107→  question: string,
   108→  chunks: KnowledgeChunk[],
   109→  questionEmbedding: number[] | null,
   110→  topK = TOP_K_CHUNKS,
   111→  maxPerDoc = MAX_CHUNKS_PER_DOC,
   112→  reserveGuided = true
   113→): KnowledgeChunk[] {
   114→  const minScore = knowledgeMinScore();
   115→  const scored = chunks
   116→    .map((c) => {
   117→      const useVector =
   118→        Array.isArray(questionEmbedding) &&
   119→        Array.isArray(c.embedding) &&
   120→        c.embedding.length === questionEmbedding.length;
   121→      const score = useVector
   122→        ? cosineSimilarity(questionEmbedding as number[], c.embedding as number[])
   123→        : bigramOverlap(question, `${c.title} ${c.text}`);
   124→      return { c, score, useVector };
   125→    })
   126→    // v0.4.15：向量模式按相关性阈值过滤（无关问题不强行注入凑数知识）；bigram 维持 >0
   127→    .filter((s) => (s.useVector ? s.score >= minScore : s.score > 0))
   128→    .sort((a, b) => b.score - a.score);
   129→  const out: KnowledgeChunk[] = [];
   130→  const picked = new Set<KnowledgeChunk>();
   131→  const perDoc = new Map<string, number>();
   132→  const push = (c: KnowledgeChunk) => {
   133→    out.push(c);
   134→    picked.add(c);
   135→    perDoc.set(c.title, (perDoc.get(c.title) || 0) + 1);
   136→  };
   137→  // 口径/指南类文档保留一个槽位：取「向量分 + 词法分」混合最高的块先行入选，
   138→  // 防止同一文档内分块边界导致正答块被其他块压过
   139→  if (reserveGuided && topK > 0) {
   140→    const guidedList = scored.filter((s) => GUIDED_DOC_KEYWORDS.some((k) => s.c.title.includes(k)));
   141→    if (guidedList.length > 0) {
   142→      const qLen = Math.max(1, question.length - 1);
   143→      const hybrid = (s: { c: KnowledgeChunk; score: number }) =>
   144→        s.score + GUIDED_BIGRAM_WEIGHT * (bigramOverlap(question, `${s.c.title} ${s.c.text}`) / qLen);
   145→      const best = guidedList.reduce((a, b) => (hybrid(b) > hybrid(a) ? b : a));
   146→      push(best.c);
   147→    }
