   150→    if (out.length >= topK) break;
   151→    if (picked.has(s.c)) continue;
   152→    const n = perDoc.get(s.c.title) || 0;
   153→    if (n >= maxPerDoc) continue;
   154→    push(s.c);
   155→  }
   156→  return out;
   157→}
