   170→/** 登记一篇业务知识文档：切块 + 逐块 embedding（失败置空走关键词降级），返回块数。
   171→ * 传入 existingDocId 时复用该 docId（编辑场景，调用方需先删除旧块）。 */
   172→export async function saveKnowledgeDoc(
   173→  dataSourceId: string,
   174→  title: string,
   175→  content: string,
   176→  createdBy: string,
   177→  existingDocId?: string
   178→): Promise<{ docId: string; chunkCount: number }> {
   179→  const docId = existingDocId || `kb_${Date.now()}_${Math.floor(Math.random() * 1e6)}`;
   180→  const chunks = chunkText(content);
   181→  if (chunks.length === 0) return { docId, chunkCount: 0 };
