   185→  const embeddings = await callEmbeddingBatch(
   186→    chunks.map((c) => `${title}\n${c}`),
   187→    'document'
   188→  ).catch(() => chunks.map(() => null));
   189→  for (let i = 0; i < chunks.length; i++) {
   190→    const embedding = embeddings[i] ?? null;
   191→    await pool.query(
   192→      'INSERT INTO knowledge_base (doc_id, data_source_id, title, chunk_text, embedding_json, created_by) VALUES (?, ?, ?, ?, ?, ?)',
   193→      [docId, dataSourceId.slice(0, 64), title.slice(0, 200), chunks[i], embedding ? JSON.stringify(embedding) : null, createdBy.slice(0, 50)]
