     1→/**
     2→ * P2-2 Ollama 多后端路由：OLLAMA_URLS=host1,host2 最少并发 + 健康检查剔除。
     3→ * 自包含模块（仅依赖 logger）；引擎解析与 LLM 主调用通道见 llmClient.ts。
     4→ * 惰性读取环境变量（ESM import 提升会使模块级读取早于 dotenv.config()，同 auth.ts/db.ts 先例）
     5→ */
     6→import { logger } from '../infra/logger';
     7→
     8→export const ollamaUrl = () => process.env.OLLAMA_URL || 'http://localhost:11434';
     9→export const ollamaTimeoutMs = () => Number(process.env.OLLAMA_TIMEOUT_MS) || 180_000;
    10→
    11→// ---------- P2-2 Ollama 多后端路由：OLLAMA_URLS=host1,host2 最少并发 + 健康检查剔除 ----------
    12→export interface OllamaBackend {
    13→  url: string;
    14→  /** 在途请求数（最少并发路由依据） */
    15→  inflight: number;
    16→  /** 熔断摘除截止时间戳（0=健康）；失败即摘除，由健康检查恢复 */
    17→  downUntil: number;
    18→}
    19→let ollamaPool: OllamaBackend[] | null = null;
    20→
    21→/** 解析后端列表：OLLAMA_URLS（逗号分隔，去重）优先，缺省回退 OLLAMA_URL 单后端 */
    22→function ollamaBackendUrls(): string[] {
    23→  const multi = String(process.env.OLLAMA_URLS || '')
    24→    .split(',')
    25→    .map((s) => s.trim().replace(/\/+$/, ''))
    26→    .filter(Boolean);
    27→  if (multi.length > 0) return [...new Set(multi)];
    28→  return [String(ollamaUrl()).replace(/\/+$/, '')];
    29→}
    30→
    31→function ollamaBackends(): OllamaBackend[] {
    32→  const urls = ollamaBackendUrls();
    33→  // 配置变更时重建池（摘除状态随配置一起重置）
    34→  if (!ollamaPool || ollamaPool.map((b) => b.url).join('|') !== urls.join('|')) {
    35→    ollamaPool = urls.map((url) => ({ url, inflight: 0, downUntil: 0 }));
    36→  }
    37→  return ollamaPool;
    38→}
    39→
    40→/** 后端摘除冷却期：失败摘除后由健康检查探测恢复；未启动健康检查时到期自动半开 */
    41→const OLLAMA_BACKEND_COOLDOWN_MS = 15_000;
    42→
    43→/** 最少并发路由：健康（含冷却到期半开）且未被排除的节点中取 inflight 最小者；
    44→ * 全部被摘除/排除时取最早恢复的节点兜底（尽力服务，不主动拒绝）。 */
    45→export function pickOllamaBackend(exclude?: Set<string>): OllamaBackend | undefined {
    46→  const now = Date.now();
    47→  const pool = ollamaBackends().filter((b) => !exclude?.has(b.url));
    48→  if (pool.length === 0) return undefined;
    49→  const healthy = pool.filter((b) => b.downUntil <= now);
    50→  const candidates = healthy.length > 0 ? healthy : [...pool].sort((a, b) => a.downUntil - b.downUntil);
    51→  return candidates.reduce((min, b) => (b.inflight < min.inflight ? b : min));
    52→}
    53→
    54→function reportOllamaSuccess(url: string): void {
    55→  const b = ollamaBackends().find((x) => x.url === url);
    56→  if (b) b.downUntil = 0;
    57→}
    58→
    59→function reportOllamaFailure(url: string): void {
    60→  const b = ollamaBackends().find((x) => x.url === url);
    61→  if (!b) return;
    62→  b.downUntil = Date.now() + OLLAMA_BACKEND_COOLDOWN_MS;
    63→  if (ollamaBackends().length > 1) {
    64→    logger.warn(`[LLM] Ollama 后端 ${url} 调用失败，已摘除（待健康检查恢复）`);
    65→  }
    66→}
    67→
    68→
    69→/** AbortController 超时中止判定（DOMException/Error 均按 name 判别） */
    70→export function isAbortErr(err: unknown): boolean {
    71→  return !!err && typeof err === 'object' && (err as { name?: unknown }).name === 'AbortError';
    72→}
    73→
    74→/** 多后端执行包装：最少并发选取 → 失败记账摘除 → 自动在次优健康后端重试（单后端直接抛出交由外层重试） */
    75→export async function withOllamaBackend<T>(fn: (baseUrl: string) => Promise<T>): Promise<T> {
    76→  const tried = new Set<string>();
    77→  let lastErr: unknown;
    78→  while (true) {
    79→    const b = pickOllamaBackend(tried);
    80→    if (!b) break;
    81→    b.inflight++;
    82→    try {
    83→      const r = await fn(b.url);
    84→      reportOllamaSuccess(b.url);
    85→      return r;
    86→    } catch (err) {
    87→      reportOllamaFailure(b.url);
    88→      tried.add(b.url);
    89→      lastErr = err;
    90→      if (ollamaBackends().length <= 1) break;
    91→    } finally {
    92→      b.inflight--;
    93→    }
    94→  }
    95→  throw lastErr;
    96→}
    97→
    98→/** 单后端健康探测（GET /api/tags，3s 超时） */
    99→export async function probeOllamaBackend(url: string): Promise<boolean> {
   100→  try {
   101→    const controller = new AbortController();
   102→    const timer = setTimeout(() => controller.abort(), 3_000);
   103→    const res = await fetch(`${url}/api/tags`, { signal: controller.signal });
   104→    clearTimeout(timer);
   105→    return res.ok;
   106→  } catch {
   107→    return false;
   108→  }
   109→}
   110→
   111→let ollamaHealthTimer: ReturnType<typeof setInterval> | null = null;
   112→/** 后台健康检查：周期探测被摘除的后端，恢复即重新接入（unref 不阻塞进程退出） */
   113→export function startOllamaHealthChecks(intervalMs = 10_000): void {
   114→  if (ollamaHealthTimer) return;
   115→  ollamaHealthTimer = setInterval(() => {
   116→    const now = Date.now();
   117→    for (const b of ollamaBackends()) {
   118→      if (b.downUntil <= now) continue;
   119→      void probeOllamaBackend(b.url).then((ok) => {
   120→        if (ok) {
   121→          b.downUntil = 0;
   122→          logger.warn(`[LLM] Ollama 后端 ${b.url} 健康检查通过，恢复接入`);
   123→        }
   124→      });
   125→    }
   126→  }, intervalMs);
   127→  ollamaHealthTimer?.unref();
   128→}
   129→
   130→/** 供测试/诊断读取后端状态快照 */
   131→export function getOllamaBackendStates(): OllamaBackend[] {
   132→  return ollamaBackends().map((b) => ({ ...b }));
   133→}
   134→
   135→/** 测试用：重置后端池与健康检查定时器 */
   136→export function resetOllamaBackendsForTest(): void {
   137→  ollamaPool = null;
   138→  if (ollamaHealthTimer) {
   139→    clearInterval(ollamaHealthTimer);
   140→    ollamaHealthTimer = null;
   141→  }
   142→}
